import java.util.HashMap;
import java.util.Map;
class Solution {
    public int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> seen = new HashMap<>(); // Earlier values and indices.
        for (int i = 0; i < nums.length; i++) { // Visit each index once.
            int need = target - nums[i]; // Compute complement.
            if (seen.containsKey(need)) return new int[]{seen.get(need), i}; // Return pair.
            seen.put(nums[i], i); // Save current value after lookup.
        }
        return new int[0]; // Defensive fallback.
    }
}

