#include <unordered_map>
#include <vector>
using namespace std;
class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        unordered_map<int, int> seen; // Earlier values and indices.
        for (int i = 0; i < (int)nums.size(); ++i) { // Visit each index.
            int need = target - nums[i]; // Compute complement.
            auto it = seen.find(need); // Search earlier values.
            if (it != seen.end()) return {it->second, i}; // Return matching indices.
            seen[nums[i]] = i; // Save current value after lookup.
        }
        return {}; // Defensive fallback.
    }
};

