import java.util.HashMap;
import java.util.Map;
class Solution {
    public int lengthOfLongestSubstring(String s) {
        Map<Character, Integer> last = new HashMap<>(); // Latest index for each character.
        int left = 0, best = 0; // Current window start and best length.
        for (int right = 0; right < s.length(); right++) { // Expand the window.
            char ch = s.charAt(right); // Read current character.
            if (last.containsKey(ch) && last.get(ch) >= left) { // Duplicate is in window.
                left = last.get(ch) + 1; // Jump past the previous occurrence.
            }
            last.put(ch, right); // Save this occurrence's index.
            best = Math.max(best, right - left + 1); // Update longest valid window.
        }
        return best; // Return maximum length.
    }
}

