#include <algorithm>
#include <string>
#include <unordered_map>
using namespace std;
class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        unordered_map<char, int> last; // Most recent index of each character.
        int left = 0, best = 0; // Window start and best length.
        for (int right = 0; right < (int)s.size(); ++right) { // Expand the window.
            char ch = s[right]; // Current character.
            if (last.count(ch) && last[ch] >= left) { // Duplicate lies in the window.
                left = last[ch] + 1; // Move beyond its earlier occurrence.
            }
            last[ch] = right; // Record current index.
            best = max(best, right - left + 1); // Update best window length.
        }
        return best; // Return maximum length.
    }
};

