class Solution {
    private int[] expand(String s, int left, int right) {
        while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) { // Matching pair.
            left--; // Expand left.
            right++; // Expand right.
        }
        return new int[]{left + 1, right - left - 1}; // Return valid start and length.
    }
    public String longestPalindrome(String s) {
        int bestStart = 0, bestLen = 1; // Any single character is a palindrome.
        for (int center = 0; center < s.length(); center++) { // Try every center.
            int[][] ranges = {expand(s, center, center), expand(s, center, center + 1)}; // Odd/even.
            for (int[] range : ranges) { // Examine both center types.
                if (range[1] > bestLen) { bestStart = range[0]; bestLen = range[1]; } // Keep longer.
            }
        }
        return s.substring(bestStart, bestStart + bestLen); // Return best range.
    }
}

