#include <string>
#include <utility>
using namespace std;
class Solution {
    pair<int, int> expand(const string& s, int left, int right) {
        while (left >= 0 && right < (int)s.size() && s[left] == s[right]) { // Matching pair.
            --left; // Expand to the left.
            ++right; // Expand to the right.
        }
        return {left + 1, right - left - 1}; // Return valid start and length.
    }
public:
    string longestPalindrome(string s) {
        int bestStart = 0, bestLen = 1; // Single characters are palindromes.
        for (int center = 0; center < (int)s.size(); ++center) { // Try every center.
            auto odd = expand(s, center, center); // Odd-length center.
            auto even = expand(s, center, center + 1); // Even-length center.
            for (auto range : {odd, even}) { // Compare both candidates.
                if (range.second > bestLen) { bestStart = range.first; bestLen = range.second; } // Keep longer.
            }
        }
        return s.substr(bestStart, bestLen); // Return longest palindrome.
    }
};

