class Solution:
    def reverse(self, x: int) -> int:
        sign = -1 if x < 0 else 1
        value = abs(x)
        result = 0
        limit = 2**31 - 1 if sign > 0 else 2**31
        while value:
            digit = value % 10
            if result > limit // 10 or (result == limit // 10 and digit > limit % 10):
                return 0
            result = result * 10 + digit
            value //= 10
        return sign * result

