class Solution {
    public String longestCommonPrefix(String[] strs) {
        if (strs.length == 0) return ""; // Defensive empty-list case.
        String first = strs[0]; // Reference string.
        for (int i = 0; i < first.length(); i++) { // Test each prefix position.
            char ch = first.charAt(i); // Expected character at this position.
            for (int j = 1; j < strs.length; j++) { // Compare all other strings.
                if (i >= strs[j].length() || strs[j].charAt(i) != ch) { // Boundary or mismatch.
                    return first.substring(0, i); // Return matching prefix only.
                }
            }
        }
        return first; // Entire reference string is common.
    }
}

