#include <string>
#include <vector>
using namespace std;
class Solution {
public:
    string longestCommonPrefix(vector<string>& strs) {
        if (strs.empty()) return ""; // Defensive empty-list case.
        const string& first = strs[0]; // Reference string.
        for (int i = 0; i < (int)first.size(); ++i) { // Check each prefix position.
            for (int j = 1; j < (int)strs.size(); ++j) { // Compare all other strings.
                if (i >= (int)strs[j].size() || strs[j][i] != first[i]) { // Boundary or mismatch.
                    return first.substr(0, i); // Return shared prefix.
                }
            }
        }
        return first; // Entire first string is common.
    }
};

