class Solution {
    public ListNode removeNthFromEnd(ListNode head, int n) {
        ListNode dummy = new ListNode(0, head); // Supports head removal.
        ListNode slow = dummy, fast = dummy;
        for (int i = 0; i < n; i++) fast = fast.next; // Keep n nodes between them.
        while (fast.next != null) { // Stop at the final node.
            slow = slow.next;
            fast = fast.next;
        }
        slow.next = slow.next.next; // Remove the target node.
        return dummy.next;
    }
}

