class Solution {
public:
    ListNode* removeNthFromEnd(ListNode* head, int n) {
        ListNode dummy(0, head); // Dummy node handles deleting the head.
        ListNode* slow = &dummy;
        ListNode* fast = &dummy;
        for (int i = 0; i < n; ++i) fast = fast->next; // Establish the gap.
        while (fast->next != nullptr) { // Move until fast is last.
            slow = slow->next;
            fast = fast->next;
        }
        slow->next = slow->next->next; // Bypass the node to remove.
        return dummy.next;
    }
};

