class Solution {
    public ListNode mergeTwoLists(ListNode list1, ListNode list2) {
        ListNode dummy = new ListNode(0); // Sentinel avoids head special cases.
        ListNode tail = dummy;
        while (list1 != null && list2 != null) {
            if (list1.val <= list2.val) { // Attach the smaller head.
                tail.next = list1;
                list1 = list1.next;
            } else {
                tail.next = list2;
                list2 = list2.next;
            }
            tail = tail.next; // Move result tail forward.
        }
        tail.next = (list1 != null) ? list1 : list2; // Append remainder.
        return dummy.next;
    }
}

