class Solution:
    def generateParenthesis(self, n: int) -> list[str]:
        result, path = [], []
        def dfs(opened, closed):
            if len(path) == 2 * n:
                result.append("".join(path)); return
            if opened < n:
                path.append("("); dfs(opened + 1, closed); path.pop()
            if closed < opened:
                path.append(")"); dfs(opened, closed + 1); path.pop()
        dfs(0, 0)
        return result

