        if (remaining == 0) { result.add(new ArrayList<>(path)); return; }
        for (int i = start; i < c.length && c[i] <= remaining; i++) {
            path.add(c[i]); dfs(c, i, remaining - c[i]); path.remove(path.size() - 1);
        }
