class Solution {
    public int firstMissingPositive(int[] nums) {
        int n = nums.length; // The answer is at most n + 1.
        for (int i = 0; i < n; i++) { // Place useful values into home slots.
            while (nums[i] >= 1 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) { // Avoid duplicate loop.
                int target = nums[i] - 1; // Value v belongs at index v - 1.
                int temp = nums[i]; // Save the value being moved.
                nums[i] = nums[target]; // Move destination value to current slot.
                nums[target] = temp; // Put desired value into its home slot.
            }
        }
        for (int i = 0; i < n; i++) { // Find the first incorrect slot.
            if (nums[i] != i + 1) return i + 1; // This positive integer is missing.
        }
        return n + 1; // All values from 1 through n are present.
    }
}

