#include <utility>
#include <vector>
using namespace std;
class Solution {
public:
    int firstMissingPositive(vector<int>& nums) {
        int n = (int)nums.size(); // The answer cannot exceed n + 1.
        for (int i = 0; i < n; ++i) { // Move useful values to home indices.
            while (nums[i] >= 1 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) { // Avoid duplicates.
                int target = nums[i] - 1; // Value v belongs at index v - 1.
                swap(nums[i], nums[target]); // Put value into its home slot.
            }
        }
        for (int i = 0; i < n; ++i) { // Check expected values in order.
            if (nums[i] != i + 1) return i + 1; // First mismatch is missing.
        }
        return n + 1; // All values 1 through n are present.
    }
};

