        nodes.push(root); // Start at root.
        while (!nodes.empty()) {
            int levelSize = static_cast<int>(nodes.size()); // Current level only.
            vector<int> level;
            for (int i = 0; i < levelSize; ++i) {
                TreeNode* node = nodes.front();
                nodes.pop();
                level.push_back(node->val);
                if (node->left != nullptr) nodes.push(node->left); // Next level.
                if (node->right != nullptr) nodes.push(node->right);
            }
            result.push_back(level);
        }
        return result;
    }
