class Solution {
    public int maxProfit(int[] prices) {
        int lowest = prices[0]; // Cheapest price seen so far.
        int best = 0; // A no-trade result has zero profit.
        for (int i = 1; i < prices.length; i++) { // Visit later days.
            best = Math.max(best, prices[i] - lowest); // Consider selling today.
            lowest = Math.min(lowest, prices[i]); // Update future buy price.
