class Solution {
    public boolean isPalindrome(String s) {
        int left = 0, right = s.length() - 1; // Opposite ends of the string.
        while (left < right) { // Continue until pointers meet.
            while (left < right && !Character.isLetterOrDigit(s.charAt(left))) left++; // Skip left punctuation.
            while (left < right && !Character.isLetterOrDigit(s.charAt(right))) right--; // Skip right punctuation.
            if (Character.toLowerCase(s.charAt(left)) != Character.toLowerCase(s.charAt(right))) return false; // Compare.
            left++; // Move left inward.
            right--; // Move right inward.
        }
        return true; // All relevant pairs matched.
    }
}

