    bool isPalindrome(string s) {
        int left = 0, right = (int)s.size() - 1; // Opposite ends.
        while (left < right) { // Stop at the center.
            while (left < right && !isalnum(static_cast<unsigned char>(s[left]))) ++left; // Skip ignored left chars.
            while (left < right && !isalnum(static_cast<unsigned char>(s[right]))) --right; // Skip ignored right chars.
            if (tolower(static_cast<unsigned char>(s[left])) != tolower(static_cast<unsigned char>(s[right]))) return false; // Compare.
            ++left; // Move left inward.
            --right; // Move right inward.
        }
        return true; // Every relevant pair matched.
    }
};

