class Solution {
    private Map<Node, Node> clones = new HashMap<>(); // Original -> copy.

    public Node cloneGraph(Node node) {
        if (node == null) return null;
        if (clones.containsKey(node)) return clones.get(node); // Reuse copy.
        Node copy = new Node(node.val);
        clones.put(node, copy); // Store before exploring cyclic edges.
        for (Node neighbor : node.neighbors) {
            copy.neighbors.add(cloneGraph(neighbor)); // Link to cloned neighbor.
        }
        return copy;
    }
}

