        Node* copy = new Node(node->val);
        clones[node] = copy; // Register before recursive calls.
        for (Node* neighbor : node->neighbors) {
            copy->neighbors.push_back(cloneGraph(neighbor)); // Clone each edge.
        }
        return copy;
    }
};

