    public void reorderList(ListNode head) {
        if (head == null || head.next == null) return;
        ListNode slow = head, fast = head; // Find midpoint.
        while (fast.next != null && fast.next.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        ListNode second = slow.next; // Second-half head.
        slow.next = null; // Split the list.
        ListNode previous = null;
        while (second != null) { // Reverse second half.
            ListNode nextNode = second.next;
            second.next = previous;
            previous = second;
            second = nextNode;
        }
        ListNode first = head;
        second = previous;
        while (second != null) { // Weave the halves together.
            ListNode firstNext = first.next, secondNext = second.next;
            first.next = second;
            second.next = firstNext;
            first = firstNext;
            second = secondNext;
        }
    }
}

