class Solution {
    public int findMin(int[] nums) {
        int left = 0, right = nums.length - 1;
        while (left < right) { // Keep a nonempty candidate interval.
            int mid = left + (right - left) / 2;
            if (nums[mid] > nums[right]) left = mid + 1; // Minimum is right of mid.
            else right = mid; // Keep mid as a possible minimum.
        }
        return nums[left];
    }
}

