class Solution {
    public int[] productExceptSelf(int[] nums) {
        int n = nums.length; // Number of positions.
        int[] answer = new int[n]; // Required output array.
        int prefix = 1; // Product strictly left of current position.
        for (int i = 0; i < n; i++) { // First pass left to right.
            answer[i] = prefix; // Store exclusive prefix product.
            prefix *= nums[i]; // Extend prefix for next index.
        }
        int suffix = 1; // Product strictly right of current position.
        for (int i = n - 1; i >= 0; i--) { // Second pass right to left.
            answer[i] *= suffix; // Combine prefix and suffix.
            suffix *= nums[i]; // Extend suffix for next index left.
        }
        return answer; // Return completed output.
    }
}

