import java.util.*;

class Solution {
    public int lengthOfLIS(int[] nums) {
        int[] tails = new int[nums.length]; // Smallest tail per length.
        int size = 0;
        for (int value : nums) {
            int left = 0, right = size;
            while (left < right) { // Lower-bound search in active tails.
                int mid = left + (right - left) / 2;
                if (tails[mid] < value) left = mid + 1;
                else right = mid;
            }
            tails[left] = value; // Replace or extend the tails array.
            if (left == size) size++;
        }
        return size; // Number of attainable subsequence lengths.
    }
}

