class Solution:
    def coinChange(self, coins: list[int], amount: int) -> int:
        unreachable = amount + 1  # Larger than any useful coin count.
        dp = [unreachable] * (amount + 1)
        dp[0] = 0  # Zero coins make amount zero.
        for current_amount in range(1, amount + 1):
            for coin in coins:
                if coin <= current_amount:  # This coin fits.
