class Solution {
    public int search(int[] nums, int target) {
        int left = 0, right = nums.length - 1; // Search the full array.
        while (left <= right) { // Continue while the interval is valid.
            int mid = left + (right - left) / 2; // Avoid overflow.
            if (nums[mid] == target) return mid; // Found the target.
            if (nums[mid] < target) left = mid + 1; // Search right half.
            else right = mid - 1; // Search left half.
        }
        return -1; // Target is absent.
    }
}

