class Solution {
    private List<List<Integer>> result = new ArrayList<>();
    private List<Integer> path = new ArrayList<>();
    private List<List<Integer>> graph;
    private int target;

    private void dfs(int node) {
        if (node == target) {
            result.add(new ArrayList<>(path)); // Save a copy of this path.
            return;
        }
        for (int neighbor : graph.get(node)) {
            path.add(neighbor); // Choose an edge.
            dfs(neighbor);
            path.remove(path.size() - 1); // Backtrack for the next route.
        }
    }

    public List<List<Integer>> allPathsSourceTarget(int[][] input) {
        graph = new ArrayList<>();
        for (int[] neighbors : input) {
            List<Integer> list = new ArrayList<>();
            for (int neighbor : neighbors) list.add(neighbor);
            graph.add(list);
        }
        target = input.length - 1;
        path.add(0);
        dfs(0);
        return result;
    }
}

