                    dp[i][j] = 1 + dp[i - 1][j - 1]; // Extend matching subsequence.
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]); // Skip one.
                }
            }
        }
        return dp[m][n];
    }
}

